<?php
$stats = [
    'books'=>(int)query('SELECT COUNT(*) FROM books WHERE archived_at IS NULL')->fetchColumn(),
    'copies'=>(int)query('SELECT COUNT(*) FROM copies WHERE archived_at IS NULL')->fetchColumn(),
    'issued'=>(int)query('SELECT COUNT(*) FROM loans WHERE returned_at IS NULL')->fetchColumn(),
    'overdue'=>(int)query('SELECT COUNT(*) FROM loans WHERE returned_at IS NULL AND due_date<CURDATE()')->fetchColumn()
];
$pending = query("SELECT r.*,b.title,b.icon,u.name FROM requests r JOIN books b ON b.id=r.book_id JOIN users u ON u.id=r.user_id WHERE r.status='pending' ORDER BY r.created_at")->fetchAll();
$readerSearch = isset($_GET['reader']) && is_string($_GET['reader']) ? mb_substr(trim($_GET['reader']),0,120) : '';
$readerParams = []; $readerWhere = 'u.archived_at IS NULL';
if ($readerSearch !== '') { $readerWhere.=' AND (u.name LIKE ? OR u.email LIKE ?)'; $readerParams[]='%'.$readerSearch.'%';$readerParams[]='%'.$readerSearch.'%'; }
$readerCount=(int)query('SELECT COUNT(*) FROM users u WHERE '.$readerWhere,$readerParams)->fetchColumn();
$readerPage=max(1,min(max(1,(int)ceil($readerCount/20)),(int)($_GET['p']??1))); $readerOffset=($readerPage-1)*20;
$readers = query('SELECT u.* FROM users u WHERE '.$readerWhere." ORDER BY u.id LIMIT 20 OFFSET $readerOffset",$readerParams)->fetchAll();
$loans=active_loans(); $byUser=[]; foreach ($loans as $loan) $byUser[$loan['user_id']][]=$loan;
$available = query(BOOK_SELECT.' WHERE b.archived_at IS NULL HAVING available>0 ORDER BY b.title')->fetchAll();
?>
<div class="stats"><article class="panel"><span>Всего книг</span><strong class="purple"><?= $stats['books'] ?></strong><small class="muted">Экземпляров: <?= $stats['copies'] ?></small></article><article class="panel"><span>Выдано</span><strong class="blue"><?= $stats['issued'] ?></strong><small class="muted">Активных выдач</small></article><article class="panel stat-danger"><span>Просрочено</span><strong class="red"><?= $stats['overdue'] ?></strong><small class="muted">По текущей дате</small></article></div>
<?php if ($pending): ?><section class="panel section-gap"><h2><span class="purple">▣</span> Заявки на выдачу <span class="genre"><?= count($pending) ?></span></h2><p class="muted subtitle">Выдайте книгу по заявке или отклоните её</p><?php foreach ($pending as $request): ?><div class="request-row"><span class="mini-icon"><?= icon($request['icon']) ?></span><div class="grow"><strong><?= e($request['title']) ?></strong><p class="muted"><?= e($request['name']) ?> · <?= format_date($request['created_at']) ?></p></div><div class="inline"><button class="button small primary" data-issue-user="<?= $request['user_id'] ?>" data-user-name="<?= e($request['name']) ?>" data-book-id="<?= $request['book_id'] ?>" data-request-id="<?= $request['id'] ?>">Выдать</button><form method="post"><?= csrf_input() ?><input type="hidden" name="action" value="reject_request"><input type="hidden" name="request_id" value="<?= $request['id'] ?>"><button class="button small outline">Отклонить</button></form></div></div><?php endforeach; ?></section><?php endif; ?>
<section class="panel section-gap"><h1><span class="purple">♧</span> Управление читателями</h1><p class="muted subtitle">Выдавайте, принимайте и продлевайте книги</p>
<form method="get" class="reader-search"><input type="hidden" name="page" value="manage"><input type="search" name="reader" value="<?= e($readerSearch) ?>" placeholder="Имя или email читателя" aria-label="Поиск читателя"><button class="button outline">Найти</button></form>
<?php foreach ($readers as $reader): ?>
<article class="reader-card"><div class="reader-header"><span class="avatar"><?= e(mb_strtoupper(mb_substr($reader['name'],0,2))) ?></span><div class="grow"><h2><?= e($reader['name']) ?><?= $reader['role']==='admin' ? ' (администратор)' : '' ?></h2><p class="muted">Билет № <?= str_pad((string)$reader['id'],5,'0',STR_PAD_LEFT) ?> · <?= e($reader['email']) ?></p></div><div class="inline"><?php if ($reader['role']==='reader'): ?><button class="icon-button" data-open="reader-<?= $reader['id'] ?>" title="Изменить данные читателя" aria-label="Изменить данные <?= e($reader['name']) ?>">✎</button><?php endif; ?><button class="button small outline" data-issue-user="<?= $reader['id'] ?>" data-user-name="<?= e($reader['name']) ?>">▣ Выдать</button></div></div>
<?php if (isset($byUser[$reader['id']])): ?><div class="reader-loans"><p class="eyebrow">Активные книги</p><?php foreach ($byUser[$reader['id']] as $loan): $days=overdue_days($loan['due_date']); ?><div class="reader-loan"><span class="mini-icon"><?= icon($loan['icon']) ?></span><div class="grow"><strong><?= e($loan['title']) ?></strong><p class="muted">До <?= format_date($loan['due_date']) ?><?= $days ? ' · <span class="red">Просрочено '.$days.' дн.</span>' : '' ?></p></div><button class="icon-button" data-open="extend-<?= $loan['id'] ?>" title="Продлить срок" aria-label="Продлить <?= e($loan['title']) ?>">◷</button><button class="icon-button green" data-open="return-<?= $loan['id'] ?>" title="Принять книгу" aria-label="Принять <?= e($loan['title']) ?>">✓</button></div><?php endforeach; ?></div><?php else: ?><p class="muted no-books">Нет активных книг</p><?php endif; ?></article>
<?php if ($reader['role']==='reader'): ?><dialog id="reader-<?= $reader['id'] ?>" class="modal"><button class="close" data-close aria-label="Закрыть">×</button><h2>Данные читателя</h2><form method="post" class="form-stack"><?= csrf_input() ?><input type="hidden" name="action" value="save_reader"><input type="hidden" name="user_id" value="<?= $reader['id'] ?>"><label>Имя и фамилия<input name="name" value="<?= e($reader['name']) ?>" maxlength="120" required></label><label>Email<input name="email" type="email" value="<?= e($reader['email']) ?>" maxlength="190" required></label><button class="button primary">Сохранить</button></form><button class="button text-danger section-gap" data-open="archive-reader-<?= $reader['id'] ?>">Архивировать читателя</button></dialog>
<dialog id="archive-reader-<?= $reader['id'] ?>" class="modal"><h2>Архивировать читателя?</h2><p><?= e($reader['name']) ?> больше не сможет войти в систему. Сначала необходимо вернуть все книги. История сохранится.</p><form method="post"><?= csrf_input() ?><input type="hidden" name="action" value="archive_reader"><input type="hidden" name="user_id" value="<?= $reader['id'] ?>"><div class="modal-actions"><button class="button outline" type="button" data-close>Отмена</button><button class="button danger-button">Архивировать</button></div></form></dialog><?php endif; ?>
<?php endforeach; ?>
<?php if (!$readers): ?><p class="empty muted">Читатели не найдены.</p><?php endif; ?>
<?php if ($readerCount>20): ?><nav class="pagination" aria-label="Страницы читателей"><?php for ($i=max(1,$readerPage-3);$i<=min((int)ceil($readerCount/20),$readerPage+3);$i++): ?><a class="button small <?= $i===$readerPage ? 'primary' : 'outline' ?>" href="?page=manage&amp;reader=<?= e(urlencode($readerSearch)) ?>&amp;p=<?= $i ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?></section>
<section class="panel section-gap"><h2>История выдач и возвратов</h2><p class="muted subtitle">Последние 50 операций выдачи</p><div class="table-scroll"><table><thead><tr><th>Читатель</th><th>Книга / экземпляр</th><th>Выдана</th><th>Срок возврата</th><th>Возвращена</th></tr></thead><tbody><?php foreach (query('SELECT l.*,u.name,b.title FROM loans l JOIN users u ON u.id=l.user_id JOIN books b ON b.id=l.book_id ORDER BY l.id DESC LIMIT 50')->fetchAll() as $row): ?><tr><td><?= e($row['name']) ?></td><td><?= e($row['title']) ?> / №<?= $row['copy_id'] ?></td><td><?= format_date($row['issued_at']) ?></td><td><?= format_date($row['due_date']) ?></td><td><?= $row['returned_at'] ? format_date($row['returned_at']) : 'На руках' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<dialog id="issue-modal" class="modal issue-modal"><button class="close" data-close aria-label="Закрыть">×</button><h2>▣ Выдать книгу: <span id="issue-reader-name"></span></h2><p class="muted subtitle">Выберите книгу из доступных для выдачи</p><form method="post" id="issue-form"><?= csrf_input() ?><input type="hidden" name="action" value="issue"><input type="hidden" name="user_id" id="issue-user"><input type="hidden" name="request_id" id="issue-request" value="0"><div class="issue-grid"><?php foreach ($available as $book): ?><label class="issue-choice"><input type="radio" name="book_id" value="<?= $book['id'] ?>" required><span class="mini-icon"><?= icon($book['icon']) ?></span><span><strong><?= e($book['title']) ?></strong><small class="muted"><?= e($book['author']) ?></small><span class="genre"><?= e($book['genre']) ?></span></span></label><?php endforeach; ?></div><p id="issue-unavailable" class="red" hidden>Для книги из заявки сейчас нет свободного экземпляра. Выдача невозможна.</p><?php if (!$available): ?><p class="muted">В каталоге нет доступных экземпляров.</p><?php endif; ?><label class="section-gap">Срок чтения (дней)<input type="number" name="days" value="14" min="1" max="90" required></label><div class="modal-actions"><button type="button" class="button outline" data-close>Отмена</button><button class="button primary" id="issue-submit" <?= !$available ? 'disabled' : '' ?>>Выдать книгу</button></div></form></dialog>
<?php foreach ($loans as $loan): ?>
<dialog id="extend-<?= $loan['id'] ?>" class="modal"><button class="close" data-close aria-label="Закрыть">×</button><h2><span class="purple">◷</span> Продлить срок</h2><p class="muted subtitle">Продление срока возврата для <?= e($loan['name']) ?></p><div class="modal-book"><span class="mini-icon"><?= icon($loan['icon']) ?></span><div><strong><?= e($loan['title']) ?></strong><p class="muted"><?= e($loan['author']) ?></p></div></div><form method="post"><?= csrf_input() ?><input type="hidden" name="action" value="extend"><input type="hidden" name="loan_id" value="<?= $loan['id'] ?>"><label>Продлить на (дней)<input name="days" type="number" value="14" min="1" max="90" required></label><p class="muted">Текущий срок: <?= format_date($loan['due_date']) ?>. Для просроченной книги новый срок считается от сегодняшнего дня.</p><div class="modal-actions"><button class="button outline" type="button" data-close>Отмена</button><button class="button primary">◷ Продлить</button></div></form></dialog>
<dialog id="return-<?= $loan['id'] ?>" class="modal"><button class="close" data-close aria-label="Закрыть">×</button><h2><span class="green">✓</span> Принять книгу</h2><p class="muted subtitle">Подтвердите возврат книги от <?= e($loan['name']) ?></p><div class="modal-book"><span class="mini-icon"><?= icon($loan['icon']) ?></span><div><strong><?= e($loan['title']) ?></strong><p class="muted"><?= e($loan['author']) ?></p></div></div><form method="post"><?= csrf_input() ?><input type="hidden" name="action" value="return"><input type="hidden" name="loan_id" value="<?= $loan['id'] ?>"><div class="modal-actions"><button type="button" class="button outline" data-close>Отмена</button><button class="button green-button">✓ Принять</button></div></form></dialog>
<?php endforeach; ?>
